<script lang="ts">
 import {useLocale,text} from '$lib/shared/presentation/locale';
 import {copy,noticeText,failureCode} from '$lib/shared/presentation/copy';
 const {locale,change:changeLanguage}=useLocale();
 import {publicationStates} from './messages';
 const stateNames=$derived(publicationStates($locale));
 const pageStates=$derived<Record<string,string>>({...stateNames,ready:text($locale,'Дайын','Готово')});
 import { onMount } from 'svelte';
 import type { Account } from '$lib/features/identity/domain/account';
 import { UploadQueue, type PublishingGateway, type Revision, type ChapterChoice,type StudioProject } from '../application/publishing';
 import {movePage} from '../domain/page-order';
 import { canEdit, canSubmit } from '../domain/revision';
 let { user, projectId, gateway }: { user: Account | null; projectId: string; gateway: PublishingGateway } = $props();
 let moreChapters=$state(false),moreRevisions=$state(false),project=$state<StudioProject|null>(null),newChapter=$state(false),chapterLabel=$state(''),chapterVolume=$state(''),chapterName=$state(''),chapterOrder=$state('');
 const editor=$derived(project?.approved&&project.status==='active'&&(project.role==='owner'||project.role==='editor'));
 async function openDraft(){if(!project)return;let selected=chapterId;if(newChapter)selected=await gateway.createChapter(projectId,{label:chapterLabel,volume:chapterVolume,name:chapterName,order:chapterOrder?Number(chapterOrder):0});active=await gateway.create(projectId,selected);chapterId=selected;newChapter=false;await reload();}
 async function loadMoreChapters(){const next=await gateway.chapters(projectId,chapters.length);chapters=[...chapters,...next];moreChapters=next.length===100;}
 async function loadMoreRevisions(){const next=await gateway.revisions(projectId,revisions.length);revisions=[...revisions,...next];moreRevisions=next.length===100;}
 let chapters = $state<ChapterChoice[]>([]), revisions = $state<Revision[]>([]), active = $state<Revision | null>(null), chapterId = $state('');
 let busy = $state(false), uploading = $state(false), progress = $state(0), progressText = $state(''), error = $state(''), notice = $state('');
 let order=$state<string[]|null>(null),orderVersion=$state(0);
 const orderedPages=$derived(active?(order||active.pages.map(page=>page.id)).map(id=>active!.pages.find(page=>page.id===id)!).filter(Boolean):[]);
 function stageMove(id:string,position:number){if(active){if(order===null)orderVersion=active.version;order=movePage(order||active.pages.map(page=>page.id),id,position);}}
 let source=$state(''),credits=$state(''),confirmed=$state(false),attributionID=$state('');
 const attributionDirty=$derived(!!active&&(source!==(active.source||'')||credits!==(active.credits||'')||confirmed!==(active.rightsConfirmed===true)));
 $effect(()=>{if(active&&active.id!==attributionID){attributionID=active.id;order=null;source=active.source||'';credits=active.credits||'';confirmed=active.rightsConfirmed===true;}});
 let queue: UploadQueue | null = null;
 async function run(action: () => Promise<void>) { if (busy) return; busy = true; error = ''; notice = ''; try { await action(); } catch (failure) { error = failureCode(failure); } finally { busy = false; } }
 async function reload() { project=await gateway.project(projectId);[chapters,revisions] = await Promise.all([gateway.chapters(projectId),gateway.revisions(projectId)]);moreChapters=chapters.length===100;moreRevisions=revisions.length===100;if(!chapters.length)newChapter=true;if(!active&&revisions.length){const chosen=revisions.find(revision=>canEdit(revision.state))||revisions[0];active=await gateway.revision(chosen.id);chapterId=active.chapterId;} }
 async function refresh() { if (active) {active = await gateway.revision(active.id);const current=active;revisions=revisions.map(revision=>revision.id===current.id?current:revision);if(active.state==='ready'&&notice==='upload_received')notice='';} }
 onMount(() => {
  if (user) run(reload);
  const timer = setInterval(() => { if (active?.state === 'processing' && order===null && !busy && !uploading && document.visibilityState === 'visible') refresh().catch(() => { error = "refresh_failed"; }); }, 2500);
  return () => { clearInterval(timer); queue?.cancel(); };
 });
 async function upload(event: Event) {
  const files = Array.from((event.currentTarget as HTMLInputElement).files || []);
  if (!active || !files.length || uploading) return;
  uploading = true; error = ''; queue = new UploadQueue(gateway);
  try { const sources = await gateway.prepare(files); await queue.run(active,sources,(name,count,total,fraction) => { progress = (count + fraction) / total; progressText = `${count}/${total}: ${name}`; }); await refresh(); notice = active?.state==='ready'?'':"upload_received"; }
  catch (failure) { error = failureCode(failure); await refresh().catch(() => {}); }
  finally { uploading = false; }
 }
 async function saveOrder(){if(!active||!order)return;await gateway.reorder(active.id,orderVersion,order);order=null;await refresh();notice='saved';}
</script>
<svelte:head><title>{copy($locale,"Аударма жүктеу — Qmanga")}</title><meta name="robots" content="noindex"/></svelte:head>
<a class="auth-link" href="/studio/projects">← {text($locale,'Барлық жобалар','Все проекты')}</a><h1>{project?.titleName||text($locale,'Тарауларды басқару','Управление главами')}</h1>{#if project}<p class="project-meta">{project.teamName} · {editor?text($locale,'Тарауларды қосып, тексеруге жібере аласың','Можешь добавлять главы и отправлять на проверку'):text($locale,'Файлдарды жүктеуге қатысушы рұқсаты','Доступ участника для загрузки файлов')}</p>{/if}
{#if !user}<a class="button primary" href={'/login?returnTo='+encodeURIComponent('/studio/projects/'+projectId)}>{text($locale,'Кіру','Войти')}</a>{:else}
{#if error}<p class="form-message" role="alert">{noticeText($locale,error)}</p>{/if}{#if notice}<p class="form-message success" role="status">{noticeText($locale,notice)}</p>{/if}
<div class="workspace-grid editor-workspace"><section class="panel chapter-sidebar"><h2>{text($locale,'Тарау ашу','Открыть главу')}</h2>
<form onsubmit={event=>{event.preventDefault();void run(openDraft);}}>
<label>{text($locale,'Тарау','Глава')}<select bind:value={newChapter} disabled={busy||uploading||order!==null||attributionDirty}><option value={false}>{text($locale,'Бар тараудан таңдау','Выбрать существующую')}</option>{#if editor}<option value={true}>{text($locale,'Жаңа тарау қосу','Добавить новую главу')}</option>{/if}</select></label>
{#if newChapter&&editor}<label>{text($locale,'Тарау нөмірі немесе атауы','Номер или обозначение главы')}<input bind:value={chapterLabel} required maxlength="64" placeholder="1, 1.5, Special"/></label><label>{text($locale,'Том · міндетті емес','Том · необязательно')}<input bind:value={chapterVolume} maxlength="32"/></label><label>{text($locale,'Тарау атауы · міндетті емес','Название главы · необязательно')}<input bind:value={chapterName} maxlength="200"/></label><details><summary>{text($locale,'Тізімдегі реті','Порядок в списке')}</summary><label>{text($locale,'Бос қалса — соңына қосылады','Пусто — добавить в конец')}<input type="number" bind:value={chapterOrder} min="1" max="1000000"/></label></details>
{:else}<label>{text($locale,'Қолда бар тараулар','Существующие главы')}<select bind:value={chapterId} required><option value="">{text($locale,'Тарауды таңда','Выбери главу')}</option>{#each chapters as chapter}<option value={chapter.id}>{chapter.label} {chapter.name}</option>{/each}</select></label>{/if}
<button class="button primary" disabled={busy||uploading||order!==null||attributionDirty||(!newChapter&&!chapterId)||(newChapter&&!editor)}>{newChapter?text($locale,'Тарау қосып, черновик ашу','Добавить главу и открыть черновик'):text($locale,'Черновик ашу','Открыть черновик')}</button>
</form><p class="muted">{text($locale,'Бар черновик қайта ашылады. Жарияланған тарау түзету кезінде оқуға ашық қалады.','Существующий черновик откроется повторно. Опубликованная глава остаётся доступной во время исправления.')}</p>
{#if moreChapters}<button class="button subtle" disabled={busy} onclick={()=>run(loadMoreChapters)}>{text($locale,'Тағы тараулар','Ещё главы')}</button>{/if}<h3>{text($locale,"Тараулар мен нұсқалар","Главы и версии")}</h3>{#each revisions as revision}<button class="revision-option button subtle" disabled={busy || uploading || order!==null || attributionDirty} onclick={() => run(async () => { active = await gateway.revision(revision.id); })}>{revision.chapterLabel}: {stateNames[revision.state] || copy($locale,"Белгісіз")}</button>{:else}<p class="muted">{copy($locale,"Нұсқа әлі жоқ.")}</p>{/each}{#if moreRevisions}<button class="button subtle" disabled={busy} onclick={()=>run(loadMoreRevisions)}>{text($locale,'Тағы нұсқалар','Ещё версии')}</button>{/if}</section>
<section class="panel draft-panel">{#if active}<div class="draft-heading"><h2>{text($locale,active.chapterLabel+"-тарау","Глава "+active.chapterLabel)}</h2><p role="status">{stateNames[active.state] || copy($locale,"Белгісіз")}</p></div><nav class="draft-steps" aria-label={text($locale,"Жариялауға дайындау","Подготовка к публикации")}><a href="#draft-pages">1. {text($locale,"Файлдар","Файлы")}</a><a href="#draft-details">2. {text($locale,"Деректер","Сведения")}</a><a href="#draft-preview">3. {text($locale,"Тексеру","Проверка")}</a></nav>{#if active.note}<p class="form-message">{active.note}</p>{/if}
{#if canEdit(active.state)}<h3 id="draft-pages">1. {text($locale,"Файлдар мен реті","Файлы и порядок")}</h3><label class="upload-field">{text($locale,"Суреттерді қосу · JPEG, PNG, WebP","Добавить изображения · JPEG, PNG, WebP")}<input type="file" multiple accept="image/jpeg,image/png,image/webp" disabled={busy || uploading || order!==null} onchange={upload}/></label><p class="muted">{copy($locale,"Файлдар табиғи ретпен жүктеледі. Байланыс үзілсе, сол файлдарды қайта таңдаңыз: дайындары қайталанбайды.")}</p><p class="muted">{text($locale,"25 MiB/файл, 300 бетке дейін. Оқу нұсқалары WebP-ге автоматты өңделеді.","До 25 MiB на файл, до 300 страниц. Варианты для чтения автоматически обрабатываются в WebP.")}</p>{:else}<h3 id="draft-pages">1. {text($locale,"Беттер","Страницы")}</h3>{/if}
{#if uploading}<progress max="1" value={progress}></progress><p class="muted">{progressText}</p><button class="button subtle" onclick={() => queue?.cancel()}>{copy($locale,"Жүктеуді тоқтату")}</button>{/if}
{#if order!==null}<div class="order-notice"><p role="status">{text($locale,'Рет пен жою өзгерістері әлі сақталмады.','Изменения порядка и удаления ещё не сохранены.')}</p><div class="actions"><button class="button primary" disabled={busy||uploading} onclick={()=>run(saveOrder)}>{text($locale,'Ретті сақтау','Сохранить порядок')}</button><button class="button subtle" disabled={busy} onclick={()=>order=null}>{text($locale,'Өзгерістерді қайтару','Отменить изменения')}</button></div></div>{/if}
<ol>{#each orderedPages as page,index (page.id)}<li><div><strong>{text($locale,page.position+'-бет','Страница '+page.position)}</strong><small>{page.width}×{page.height} / {(page.bytes / 1048576).toFixed(2)} MiB / {pageStates[page.status] || copy($locale,"Белгісіз")}</small>{#if page.status==='failed'}<p class="page-error">{text($locale,"Өңдеу сәтсіз. Осы файлды қайта таңда немесе бетті ауыстыр.","Обработка не удалась. Выбери этот файл повторно или замени страницу.")}</p>{/if}</div>{#if canEdit(active.state)}<div class="row-actions"><label class="position-label">{text($locale,'Орын','Позиция')}<input type="number" min="1" max={orderedPages.length} value={index+1} disabled={busy||uploading} onchange={event=>stageMove(page.id,Number(event.currentTarget.value))}/></label><button class="button subtle" aria-label={text($locale,page.position+'-бетті жоғары жылжыту','Переместить страницу '+page.position+' вверх')} disabled={busy || uploading || index === 0} onclick={() => stageMove(page.id,index)}>↑</button><button class="button subtle" aria-label={text($locale,page.position+'-бетті төмен жылжыту','Переместить страницу '+page.position+' вниз')} disabled={busy || uploading || index === orderedPages.length - 1} onclick={() => stageMove(page.id,index+2)}>↓</button><button class="button subtle" disabled={busy||uploading} onclick={()=>{if(order===null)orderVersion=active!.version;order=(order||active!.pages.map(item=>item.id)).filter(id=>id!==page.id);}}>{copy($locale,"Жою")}</button></div>{/if}</li>{/each}</ol>
{#if canEdit(active.state)}<form id="draft-details" onsubmit={event=>{event.preventDefault();void run(async()=>{await gateway.attribution(active!.id,active!.version,source,credits,confirmed);await refresh();});}}>
<h3>2. {text($locale,'Деректер мен кредиттер','Сведения и кредиты')}</h3><label>{text($locale,'Дереккөз және жариялау құқығының негізі','Источник и основание права публикации')}<textarea bind:value={source} required minlength="8" maxlength="2000" rows="3"></textarea></label>
<label>{text($locale,'Кредиттер: авторлар мен аудармашылар','Кредиты: авторы и переводчики')}<textarea bind:value={credits} required minlength="2" maxlength="2000" rows="3"></textarea></label>
<label class="rights-check"><input type="checkbox" bind:checked={confirmed} required/>{text($locale,'Осы материалды жариялауға құқығым бар екенін растаймын','Подтверждаю наличие права на публикацию этого материала')}</label><p class="muted">{text($locale,'Бұл мәтіндер читалкада көрінеді. Жеке құжаттар мен деректерді жазба.','Эти тексты видны в читалке. Не указывай личные документы и данные.')}</p>
<button class="button subtle" disabled={busy||uploading}>{text($locale,'Деректерді сақтау','Сохранить сведения')}</button>{#if active.rightsConfirmed}<p role="status">{text($locale,'Жариялау деректері сақталған','Сведения о публикации сохранены')}</p>{/if}</form>{:else}<section id="draft-details"><h3>2. {text($locale,'Деректер мен кредиттер','Сведения и кредиты')}</h3><dl><dt>{text($locale,'Дереккөз','Источник')}</dt><dd>{active.source||'—'}</dd><dt>{text($locale,'Кредиттер','Кредиты')}</dt><dd>{active.credits||'—'}</dd></dl></section>{/if}
<section id="draft-preview"><h3>3. {text($locale,"Тексеру және жіберу","Проверка и отправка")}</h3>{#if canEdit(active.state)}<p class="muted">{text($locale,"Өңдеу аяқталып, рет пен деректер сақталған соң, читалкада тексеріп шық. Содан кейін модераторға жібер.","После обработки сохрани порядок и сведения, проверь главу в читалке и отправь модератору.")}</p>{#if attributionDirty}<p role="status">{text($locale,"Деректердегі өзгерістер әлі сақталмады.","Изменения сведений ещё не сохранены.")}</p>{/if}{#if !editor}<p class="muted">{text($locale,"Тексеруге тек редактор не команда иесі жібере алады.","Отправить на проверку может редактор или владелец команды.")}</p>{/if}<div class="actions"><button class="button subtle" disabled={busy||order!==null} onclick={() => run(refresh)}>{copy($locale,"Күйін жаңарту")}</button>{#if active.pages.length&&active.pages.every(page=>page.status==='ready')&&order===null&&!attributionDirty}<a class="button subtle" href={'/read/' + encodeURIComponent(active.releaseId) + '?preview=' + encodeURIComponent(active.id)}>{copy($locale,"Алдын ала оқу")}</a>{:else}<span class="button subtle" aria-disabled="true">{text($locale,'Алдын ала оқу өңдеуден кейін ашылады','Предпросмотр после обработки и сохранения')}</span>{/if}<button class="button primary" disabled={busy || uploading || (order!==null||attributionDirty||!editor||!canSubmit(active)||!active.rightsConfirmed)} onclick={() => run(async () => { await gateway.submit(active!.id,active!.version); await refresh(); await reload(); notice = "submitted"; })}>{copy($locale,"Тексеруге жіберу")}</button></div>{:else}<p class="muted">{active.state==='submitted'?text($locale,'Тарау модераторда. Шешім осында және хабарларда пайда болады.','Глава у модератора. Решение появится здесь и в уведомлениях.'):text($locale,'Жарияланған нұсқа өзгермейді. Түзетуге жаңа черновик ашылып, файлдар қайта жүктеледі.','Опубликованная версия сохраняется. Для исправления открой новый черновик и загрузи файлы заново.')}</p><div class="actions"><a class="button subtle" href={'/read/'+active.releaseId+'?preview='+active.id}>{text($locale,'Алдын ала оқу','Предпросмотр')}</a>{#if active.state==='published'||active.state==='changes_requested'}<button class="button primary" disabled={busy||uploading} onclick={()=>run(async()=>{active=await gateway.create(projectId,active!.chapterId);chapterId=active.chapterId;await reload();})}>{text($locale,'Түзетуге черновик ашу','Открыть черновик исправления')}</button>{:else}<a class="button subtle" href="/notifications">{text($locale,'Хабарлар','Уведомления')}</a>{/if}</div>{/if}</section>
{:else}<p class="muted">{copy($locale,"Тарауды немесе нұсқаны таңдаңыз.")}</p>{/if}</section></div>{/if}
<style>dt{font-size:13px;color:var(--muted)}dd{margin:8px 0 16px;white-space:pre-wrap;overflow-wrap:anywhere}.editor-workspace{grid-template-columns:minmax(0,1fr)}.chapter-sidebar{align-self:start}.project-meta{color:var(--muted);font-size:14px;margin:8px 0 24px}.draft-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.draft-heading p{font-size:14px}.draft-steps{display:flex;gap:12px;border-block:1px solid var(--line);margin:16px 0 24px;overflow-x:auto}.draft-steps a{display:flex;align-items:center;min-height:48px;white-space:nowrap;font-size:14px}.upload-field{border:1px dashed var(--line);padding:16px}.draft-panel h3{font-size:17px;margin:24px 0 12px;scroll-margin-top:80px}#draft-details,#draft-preview{border-top:1px solid var(--line);margin-top:28px;padding-top:12px;scroll-margin-top:80px}.page-error{font-size:14px;margin:8px 0}.chapter-sidebar form{display:grid;gap:12px}.chapter-sidebar .button{justify-self:start}summary{min-height:44px;display:flex;align-items:center;cursor:pointer;font-size:14px}@media(min-width:1000px){.editor-workspace{grid-template-columns:300px minmax(0,1fr)}}.position-label{max-width:100px;margin:0!important}.row-actions{align-items:end}.order-notice{padding:16px 0;border-block:1px solid var(--line)}.rights-check{display:flex;align-items:center;gap:12px;min-height:44px}.rights-check input{width:20px;min-height:20px;height:20px}.revision-option { width:100%; justify-content:flex-start; margin:5px 0; } ol { padding:0; list-style:none; } li { border-bottom:1px solid var(--line); padding:14px 0; display:grid; gap:8px; } small { display:block; color:var(--muted); } .row-actions,.actions { display:flex; gap:8px; flex-wrap:wrap; } .actions { margin-top:20px; } progress { width:100%; } .panel label { margin:16px 0; } h1 { overflow-wrap:anywhere; }</style>
